def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def hex_key(num):
    prime_digits = {'2', '3', '5', '7', 'B', 'D'}
    decimal_num = int(num, 16)
    count = 0
    while decimal_num > 0:
        digit = decimal_num % 10
        if str(digit) in prime_digits:
            count += 1
        decimal_num //= 10
    return count

